// AI Content Transformer: build 3 platform-formatted content assets.
// Code node has NO network access, so assets are composed deterministically
// from the incoming payload. Swap this logic for an LLM/HTTP node if needed.
try {
  const body = ($json && $json.body) ? $json.body : $json || {};

  const rawTranscript = (body.raw_transcript || '').toString().trim();
  const topic = (body.topic || '').toString().trim();
  const targetAudience = (body.target_audience || '').toString().trim();

  if (!rawTranscript && !topic) {
    return {
      json: {
        success: false,
        error: 'Missing required input: both raw_transcript and topic are empty.',
        linkedin_post: '',
        gbp_update: '',
        newsletter_snippet: '',
        linkedin_len: 0,
        gbp_len: 0,
        newsletter_len: 0,
        source: { topic, target_audience: targetAudience },
      },
    };
  }

  const safeTopic = topic || 'Key Insights';
  const safeAudience = targetAudience || 'our community';

  // Derive a few takeaways from the transcript.
  const sentences = rawTranscript
    .split(/(?<=[.!?])\s+/)
    .map((s) => s.trim())
    .filter((s) => s.length > 0);

  const takeaways = (sentences.length > 0 ? sentences.slice(0, 3) : [safeTopic]);
  const takeawayLines = takeaways.map((t, i) => (i + 1) + '. ' + t).join('\n');

  const hashtagBase = safeTopic
    .replace(/[^a-zA-Z0-9\s]/g, '')
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 3)
    .map((w) => '#' + w.charAt(0).toUpperCase() + w.slice(1));
  const hashtags = (hashtagBase.length > 0 ? hashtagBase : ['#Insights'])
    .concat(['#MarTech', '#Growth'])
    .join(' ');

  const linkedin_post =
    'Here is what ' + safeAudience + ' need to know about ' + safeTopic + '.\n\n' +
    'Key takeaways:\n' + takeawayLines + '\n\n' +
    'These insights come straight from the field and are designed to help you move faster. ' +
    'What resonates most with your team?\n\n' + hashtags;

  const gbp_update =
    'New update on ' + safeTopic + ': practical guidance for ' + safeAudience + '. ' +
    'Learn how to put this into action today. Read more and get started: https://example.com/learn-more';

  const newsletter_snippet =
    'Dear subscriber,\n\n' +
    'This week we are unpacking ' + safeTopic + ', with actionable perspective tailored for ' +
    safeAudience + '. ' + (takeaways[0] || '') + '\n\n' +
    'In the full digest we break down what this means for your roadmap and the concrete next ' +
    'steps to capture the opportunity. Read on to see how leading teams are responding.';

  return {
    json: {
      success: true,
      error: null,
      linkedin_post,
      gbp_update,
      newsletter_snippet,
      linkedin_len: linkedin_post.length,
      gbp_len: gbp_update.length,
      newsletter_len: newsletter_snippet.length,
      source: { topic: safeTopic, target_audience: safeAudience },
    },
  };
} catch (err) {
  return {
    json: {
      success: false,
      error: 'Generation failed: ' + (err && err.message ? err.message : String(err)),
      linkedin_post: '',
      gbp_update: '',
      newsletter_snippet: '',
      linkedin_len: 0,
      gbp_len: 0,
      newsletter_len: 0,
    },
  };
}

// Log formatting/QA errors for editorial review.
try {
  const data = $json || {};
  const issues = [];

  if (!data.linkedin_post) issues.push('linkedin_post missing or empty');
  else if ((data.linkedin_len || 0) < 120) issues.push('linkedin_post too short (' + (data.linkedin_len || 0) + ' chars)');

  if (!data.gbp_update) issues.push('gbp_update missing or empty');
  else if ((data.gbp_len || 0) < 30) issues.push('gbp_update too short (' + (data.gbp_len || 0) + ' chars)');

  if (!data.newsletter_snippet) issues.push('newsletter_snippet missing or empty');
  else if ((data.newsletter_len || 0) < 120) issues.push('newsletter_snippet too short (' + (data.newsletter_len || 0) + ' chars)');

  if (data.error) issues.push('generation error: ' + data.error);

  return {
    json: {
      quarantined: true,
      status: 'needs_editorial_review',
      quarantined_at: new Date().toISOString(),
      formatting_errors: issues.length > 0 ? issues : ['Unknown validation failure'],
      original_assets: {
        linkedin_post: data.linkedin_post || '',
        gbp_update: data.gbp_update || '',
        newsletter_snippet: data.newsletter_snippet || '',
      },
      source: data.source || {},
    },
  };
} catch (err) {
  return {
    json: {
      quarantined: true,
      status: 'needs_editorial_review',
      formatting_errors: ['Quarantine handler failed: ' + (err && err.message ? err.message : String(err))],
    },
  };
}
